@import "@fontsource-variable/newsreader/opsz.css";
@import "@fontsource-variable/newsreader/opsz-italic.css";
@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource/dm-mono/400.css";

/* Light (faithful): beige page #FEF9EF, cream tiles #F5EEE1, dark-cream hairlines #D1C9BF,
   midnight text #2A2B2F, grey secondary text #515151, terracotta #B05A36 for pills and italics. */
:root {
  --background: oklch(0.982 0.017 85);
  --foreground: oklch(0.275 0.008 270);
  --card: oklch(0.953 0.021 85);
  --card-foreground: oklch(0.275 0.008 270);
  --popover: oklch(0.982 0.017 85);
  --popover-foreground: oklch(0.275 0.008 270);
  --primary: oklch(0.545 0.119 46);
  --primary-foreground: oklch(0.982 0.017 85);
  --secondary: oklch(0.953 0.021 85);
  --secondary-foreground: oklch(0.275 0.008 270);
  --muted: oklch(0.953 0.021 85);
  --muted-foreground: oklch(0.43 0 0);
  --accent: oklch(0.915 0.025 85);
  --accent-foreground: oklch(0.275 0.008 270);
  --destructive: oklch(0.577 0.2 27);
  --destructive-foreground: oklch(0.982 0.017 85);
  --border: oklch(0.846 0.02 80);
  --input: oklch(0.43 0 0);
  --ring: oklch(0.545 0.119 46);
  --highlight: oklch(0.545 0.119 46);
  --highlight-foreground: oklch(0.982 0.017 85);
  --glow: oklch(0.74 0.078 55);
  --chart-1: oklch(0.545 0.119 46);
  --chart-2: oklch(0.755 0.12 154);
  --chart-3: oklch(0.75 0.07 52);
  --chart-4: oklch(0.62 0.12 150);
  --chart-5: oklch(0.36 0.07 150);
  --sidebar: oklch(0.953 0.021 85);
  --sidebar-foreground: oklch(0.275 0.008 270);
  --sidebar-primary: oklch(0.545 0.119 46);
  --sidebar-primary-foreground: oklch(0.982 0.017 85);
  --sidebar-accent: oklch(0.915 0.025 85);
  --sidebar-accent-foreground: oklch(0.275 0.008 270);
  --sidebar-border: oklch(0.846 0.02 80);
  --sidebar-ring: oklch(0.545 0.119 46);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Newsreader Variable", Georgia, "Times New Roman", serif;
  --typeface-mono: "DM Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  /* 90rem wide, so the content is 1248px at 1440 (the original's own max width) */
  --page-width: 90rem;
  --page-gutter: clamp(1.25rem, 7vw - 0.5rem, 6rem);
  --section-y: clamp(3rem, 4.812vw + 1.869rem, 6.2rem);
}

/* Dark: a sibling in the same spirit, midnight paper with a lifted terracotta. */
.dark {
  --background: oklch(0.225 0.008 270);
  --foreground: oklch(0.96 0.02 85);
  --card: oklch(0.275 0.01 265);
  --card-foreground: oklch(0.96 0.02 85);
  --popover: oklch(0.275 0.01 265);
  --popover-foreground: oklch(0.96 0.02 85);
  --primary: oklch(0.69 0.125 45);
  --primary-foreground: oklch(0.2 0.008 270);
  --secondary: oklch(0.31 0.01 265);
  --secondary-foreground: oklch(0.96 0.02 85);
  --muted: oklch(0.275 0.01 265);
  --muted-foreground: oklch(0.76 0.015 80);
  --accent: oklch(0.34 0.012 265);
  --accent-foreground: oklch(0.96 0.02 85);
  --destructive: oklch(0.7 0.19 25);
  --destructive-foreground: oklch(0.2 0.008 270);
  --border: oklch(0.96 0.02 85 / 16%);
  --input: oklch(0.96 0.02 85 / 45%);
  --ring: oklch(0.69 0.125 45);
  --highlight: oklch(0.76 0.11 50);
  --highlight-foreground: oklch(0.2 0.008 270);
  --glow: oklch(0.6 0.12 48);
  --chart-1: oklch(0.69 0.125 45);
  --chart-2: oklch(0.78 0.12 154);
  --chart-3: oklch(0.8 0.07 55);
  --chart-4: oklch(0.66 0.12 150);
  --chart-5: oklch(0.5 0.08 150);
  --sidebar: oklch(0.25 0.009 268);
  --sidebar-foreground: oklch(0.96 0.02 85);
  --sidebar-primary: oklch(0.69 0.125 45);
  --sidebar-primary-foreground: oklch(0.2 0.008 270);
  --sidebar-accent: oklch(0.34 0.012 265);
  --sidebar-accent-foreground: oklch(0.96 0.02 85);
  --sidebar-border: oklch(0.96 0.02 85 / 16%);
  --sidebar-ring: oklch(0.69 0.125 45);
}
